CREATE TABLE IF NOT EXISTS outbox(event_id varchar(128) COLLATE utf8mb4_bin PRIMARY KEY,aggregate_id varchar(128) COLLATE utf8mb4_bin NOT NULL,aggregate_version bigint NOT NULL,event_type varchar(64) NOT NULL,payload json NOT NULL,payload_hash char(64) NOT NULL,state varchar(16) NOT NULL,attempt int NOT NULL DEFAULT 0,lease_token varchar(128),lease_until datetime(6),next_attempt_at datetime(6) NOT NULL,created_at datetime(6) NOT NULL,published_at datetime(6),INDEX pending(state,next_attempt_at,event_id),INDEX expired(state,lease_until,event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
